                   if (!res.ok) throw new Error(`Image fetch failed`);
                   const blob = await res.blob();
                   await db.messages.add({
                     role: 'bot',
                     content: '',
                     imageUrl: fullUrl,
                     imageBlob: blob,
                     timestamp: Date.now(),
                     status: 'complete',
                   });
                 } catch (err) {
                   await db.messages.add({
                      role: 'bot',
                      content: 'Image generated but failed to download. Check console.',
                      imageUrl: fullUrl,
                      timestamp: Date.now(),
                      status: 'error'
                   });
                 }
               }
            }
          } catch (e) {}
        };
        wsRef.current = ws;
      } catch (e) {}
    };
    connect();
    return () => {
      if (wsRef.current) wsRef.current.close();
    };
